11	    *, *::before, *::after { box-sizing: border-box; }
12	    html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
13	    @media (prefers-reduced-motion: no-preference) { html { scroll-behavior: smooth; } }
14	    hr { border: 0; border-top: 1px solid; opacity: 0.25; }
15	    abbr[title] { text-decoration: underline dotted; cursor: help; }
16	    table { width: 100%; border-collapse: collapse; }
17	    caption { text-align: start; font-weight: 600; }
18	    :target { scroll-margin-block: 1rem; }
