20	      min-height: 100vh;
21	      min-height: 100dvh;
22	      margin: 0 auto;
23	      max-width: 65ch;
24	      padding: 1rem;
25	      font-family: system-ui, sans-serif;
26	      line-height: 1.5;
27	    }
28	    input, button, textarea, select { font: inherit; color: inherit; }
29	    h1, h2, h3, h4, h5, h6 { line-height: 1.2; text-wrap: balance; }
30	    p { text-wrap: pretty; }
31	    p, li, h1, h2, h3, h4, h5, h6, figcaption, blockquote { overflow-wrap: break-word; }
32	    img, svg, video, canvas, picture, iframe { max-width: 100%; display: block; }
33	    img, video { height: auto; }
34	    pre, code, kbd, samp { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.9em; }
35	    pre code { font-size: inherit; }
36	    pre { overflow-x: auto; tab-size: 2; }
37	    img { font-style: italic; }
38	    svg:not([width]) { height: auto; }
39	    :where(button, input, textarea, select) { line-height: inherit; }
40	    ::selection { background: color-mix(in srgb, Highlight 40%, transparent); }
41	    th { border-block-end: 1px solid color-mix(in srgb, currentColor 25%, transparent); }
42	    td { font-variant-numeric: tabular-nums; }
43	    th, td { padding: 0.25em 0.5em; text-align: start; vertical-align: top; }
44	    sub, sup { line-height: 0; }
45	    a { text-underline-offset: 0.15em; }
46	    button:not(:disabled), [role="button"], summary, label[for] { cursor: pointer; }
47	    textarea { resize: vertical; }
48	    [hidden] { display: none !important; }
49	    :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
50	    @media (prefers-reduced-motion: reduce) {
51	      *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
52	    }
